// TWO REQUESTS PER BAND, one per token.
//
// A band's NO side is its OWN order book with its own resting orders and its
// own spread. The edge engine has always derived it as the complement of the
// YES book - a NO ask at q read off a YES bid at 1-q - which holds only where
// minting and merging keep the two tokens in lockstep. What a desk actually
// pays sits on the NO book itself, so every NO edge quoted from the mirror
// was a model of a price rather than a price.
//
// max_bands_per_run still counts BANDS, which is what it says. Two requests
// per band means the cap and the request count differ by up to 2x; the Fetch
// node's batching (20 per 250ms) is what paces them either way.
const cfg = $('Config').first().json;
const template = String(cfg.clob_book_url || '');
if (!template.includes('{token}')) {
  throw new Error(
    'clob_book_url must contain the placeholder {token}. Got: ' + template +
    '  -- the workflow substitutes each band\'s token id for it.');
}

const bands = $('Load live bands').all().map(i => i.json).flat();
const limit = Number(cfg.max_bands_per_run || 0) || 0;

const out = [];
let counted = 0;
for (const b of bands) {
  if (!b || !b.band_id || !b.token_yes) continue;
  if (limit && counted >= limit) break;
  counted++;
  const common = { band_id: b.band_id, token_yes: b.token_yes,
                   condition_id: b.condition_id ?? null };
  out.push({ json: { ...common, side: 'YES', token_id: b.token_yes,
    book_url: template.replace('{token}', encodeURIComponent(b.token_yes)) } });
  // The NO token is optional. A band discovered before P0.2 carried both ids
  // has only the YES one, and one side captured beats neither.
  if (b.token_no) {
    out.push({ json: { ...common, side: 'NO', token_id: b.token_no,
      book_url: template.replace('{token}', encodeURIComponent(b.token_no)) } });
  }
}
if (out.length === 0) {
  throw new Error('No bands with a token_yes came back from Supabase. ' +
                  'Check that bands.token_yes is populated.');
}
return out;

// Build one book_snapshots row per BAND, carrying both of its books.
//
// CONFIRMED against the live database (sql/ad4_99_verify.sql section 7):
//   bid_levels / ask_levels   integer LEVEL COUNTS - NOT ladders
//   raw_book                  jsonb {"bids":[{price,size}],"asks":[...]}
//   ask_usd_1c .. ask_usd_25c numeric, CUMULATIVE USD within N cents of touch
//   ask_total_usd             numeric, whole-side USD
//
// Every one of those columns still means the YES book, exactly as before. The
// NO book lands beside them in no_best_bid, no_best_ask and no_book, which is
// additive so nothing downstream shifts under it.
//
// market_state is a verbatim port of scripts/market_state.py:classify().
// PRICE IS CHECKED BEFORE SIDES - a band at ask 0.001 with no bids is
// DEAD_LOSER, not ONE_SIDED. Getting that order wrong mislabelled 190 of
// 231 rows earlier in this project.
const DEAD_LOSER_MAX_ASK = 0.02;
const DEAD_WINNER_MIN_BID = 0.96;
const WIDE_SPREAD_MIN = 0.10;

function classify(bestBid, bestAsk) {
  const hasBid = bestBid !== null && bestBid !== undefined;
  const hasAsk = bestAsk !== null && bestAsk !== undefined;
  if (!hasBid && !hasAsk) return 'NO_BOOK';
  if (hasAsk && bestAsk <= DEAD_LOSER_MAX_ASK) return 'DEAD_LOSER';
  if (hasBid && bestBid >= DEAD_WINNER_MIN_BID) return 'DEAD_WINNER';
  if (!hasBid || !hasAsk) return 'ONE_SIDED';
  return (bestAsk - bestBid) > WIDE_SPREAD_MIN ? 'WIDE' : 'LIVE';
}

// Accepts {price,size} objects or [price,size] pairs, whichever the API sends.
function ladder(levels, side) {
  const out = (levels || [])
    .map(l => ({
      price: Number(l && l.price !== undefined ? l.price : (Array.isArray(l) ? l[0] : NaN)),
      size:  Number(l && l.size  !== undefined ? l.size
                    : (l && l.amount !== undefined ? l.amount
                    : (Array.isArray(l) ? l[1] : NaN))),
    }))
    .filter(l => Number.isFinite(l.price) && Number.isFinite(l.size) && l.size > 0 && l.price > 0);
  out.sort((a, b) => side === 'bid' ? b.price - a.price : a.price - b.price);
  return out;
}

const r6 = v => (v === null || v === undefined || !Number.isFinite(v)) ? null : Number(v.toFixed(6));

// Cumulative USD within 1/2/5/10/25 cents of the touch, plus the whole side.
// CUMULATIVE, not per-tier: ask_usd_5c includes everything inside 2c and 1c.
// ad4_synth_levels() in sql/ad4_13_reconcile.sql differences them back apart,
// so the two must agree on this.
function tiers(levels, side) {
  const out = { c1: 0, c2: 0, c5: 0, c10: 0, c25: 0, total: 0 };
  if (!levels.length) return out;
  const touch = levels[0].price;
  const E = 1e-9;
  for (const l of levels) {
    const usd = l.price * l.size;
    const d = side === 'ask' ? (l.price - touch) : (touch - l.price);
    out.total += usd;
    if (d <= 0.01 + E) out.c1 += usd;
    if (d <= 0.02 + E) out.c2 += usd;
    if (d <= 0.05 + E) out.c5 += usd;
    if (d <= 0.10 + E) out.c10 += usd;
    if (d <= 0.25 + E) out.c25 += usd;
  }
  return out;
}

function parse(res) {
  if (!res || res.error || (!res.bids && !res.asks && !res.book)) return null;
  const src = res.book || res;
  const bidLevels = ladder(src.bids || src.buys, 'bid');
  const askLevels = ladder(src.asks || src.sells, 'ask');
  if (!bidLevels.length && !askLevels.length) return null;
  return { src, bidLevels, askLevels };
}

const requests = $('Build request list').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

// Responses are index-aligned with requests: the HTTP node runs once per item.
// Both of a band's requests are folded back onto one band here.
const byBand = new Map();
for (let i = 0; i < requests.length; i++) {
  const req = requests[i];
  if (!byBand.has(req.band_id)) byBand.set(req.band_id, { req, YES: null, NO: null });
  byBand.get(req.band_id)[req.side === 'NO' ? 'NO' : 'YES'] = parse(responses[i]);
}

const observedAt = new Date().toISOString();
const hourUtc = new Date(observedAt).getUTCHours();
const rows = [];
let failed = 0, noFailed = 0, bothSides = 0;

for (const [bandId, slot] of byBand) {
  // A band with no usable YES book has no row at all, as before: the YES
  // columns are not nullable and every downstream view reads them.
  if (!slot.YES) { failed++; continue; }

  const { src, bidLevels, askLevels } = slot.YES;
  const bestBid = bidLevels.length ? bidLevels[0].price : null;
  const bestAsk = askLevels.length ? askLevels[0].price : null;
  const state = classify(bestBid, bestAsk);
  const A = tiers(askLevels, 'ask');
  const D = tiers(bidLevels, 'bid');

  const row = {
    band_id: bandId,
    observed_at: observedAt,
    snapshot_hour_utc: hourUtc,
    best_bid: bestBid,
    best_ask: bestAsk,
    mid: (bestBid !== null && bestAsk !== null) ? r6((bestBid + bestAsk) / 2) : null,
    spread: (bestBid !== null && bestAsk !== null) ? r6(bestAsk - bestBid) : null,
    market_state: state,
    tradeable: state === 'LIVE' || state === 'WIDE',
    bid_levels: bidLevels.length,
    ask_levels: askLevels.length,
    raw_book: { bids: bidLevels, asks: askLevels },
    ask_usd_1c: r6(A.c1),   bid_usd_1c: r6(D.c1),
    ask_usd_2c: r6(A.c2),   bid_usd_2c: r6(D.c2),
    ask_usd_5c: r6(A.c5),   bid_usd_5c: r6(D.c5),
    ask_usd_10c: r6(A.c10), bid_usd_10c: r6(D.c10),
    ask_usd_25c: r6(A.c25), bid_usd_25c: r6(D.c25),
    ask_total_usd: r6(A.total), bid_total_usd: r6(D.total),
    band_volume: src.volume ?? src.band_volume ?? null,
    band_volume_24hr: src.volume_24hr ?? src.volume24hr ?? src.band_volume_24hr ?? null,
    // Null until proven otherwise: an absent NO book must read as "not
    // captured", never as an empty one.
    no_best_bid: null, no_best_ask: null, no_book: null,
  };

  if (slot.NO) {
    const nb = slot.NO.bidLevels, na = slot.NO.askLevels;
    const nBestBid = nb.length ? nb[0].price : null;
    const nBestAsk = na.length ? na[0].price : null;
    const NA = tiers(na, 'ask');
    const ND = tiers(nb, 'bid');
    row.no_best_bid = nBestBid;
    row.no_best_ask = nBestAsk;
    row.no_book = {
      best_bid: nBestBid, best_ask: nBestAsk,
      mid: (nBestBid !== null && nBestAsk !== null) ? r6((nBestBid + nBestAsk) / 2) : null,
      spread: (nBestBid !== null && nBestAsk !== null) ? r6(nBestAsk - nBestBid) : null,
      market_state: classify(nBestBid, nBestAsk),
      bid_levels: nb.length, ask_levels: na.length,
      // Same cumulative tier semantics as the YES columns beside them.
      ask_usd: { c1: r6(NA.c1), c2: r6(NA.c2), c5: r6(NA.c5),
                 c10: r6(NA.c10), c25: r6(NA.c25), total: r6(NA.total) },
      bid_usd: { c1: r6(ND.c1), c2: r6(ND.c2), c5: r6(ND.c5),
                 c10: r6(ND.c10), c25: r6(ND.c25), total: r6(ND.total) },
      observed_at: observedAt,
    };
    bothSides++;
  } else {
    noFailed++;
  }

  rows.push(row);
}

const byState = {};
for (const r of rows) byState[r.market_state] = (byState[r.market_state] || 0) + 1;
return [{ json: { rows, n: rows.length, requested: byBand.size, failed,
                  no_failed: noFailed, both_sides: bothSides,
                  requests_made: requests.length, byState } }];

// Refuse to write nothing. A wrong endpoint, a changed payload shape or a
// dead token list all land here as n === 0, and this stops the run with a
// message that says which - rather than inserting zero rows and reporting
// success.
const p = $('Build snapshots').first().json;
if (p.n === 0) {
  throw new Error(
    `Parsed 0 books out of ${p.requested} requests (${p.failed} failed). ` +
    `Nothing was written. Most likely the Polymarket endpoint in Config is ` +
    `wrong for your setup, or its response shape is not {bids:[...],asks:[...]}. ` +
    `Open your original P0.3 and copy its URL across.`);
}
return [{ json: p }];

const AD4_WRITE_NODES = ["Insert snapshots"];
// AD4-WRITE-GUARD
// DID THE DATABASE ACTUALLY TAKE IT?
//
// Every write node in this workflow carries onError=continueRegularOutput so
// that one bad row cannot kill a run. The cost of that is a REFUSED write
// walks straight past it and arrives here looking healthy - which is how a
// workflow reports "ok, 0 rows" for days while the data quietly stops moving.
//
// With neverError on, a refusal arrives as the PostgREST error body instead of
// an exception, so it can be read and named. That is what this does.
function ad4WriteError(node) {
  // WHAT ACTUALLY WENT WRONG, NOT THE FIRST THING THAT LOOKED LIKE AN ERROR.
  //
  // This used to return the first item carrying a `code` or `message` and stop.
  // A Supabase gateway timeout arrives as {"data":"upstream request timeout"} -
  // no code, no message - so it was skipped ENTIRELY, and on a run where 90 of
  // 102 writes timed out the guard reported the single PGRST102 it found
  // instead. The message named a key mismatch; the cause was an overloaded
  // database. That cost an evening.
  //
  // So: classify every item, count the kinds, and report the one that
  // dominates, with the counts, so the next person reads the truth first.
  let items;
  try { items = $(node).all(); } catch (e) { return null; }
  const kinds = {};
  let first = null, n = 0;
  for (const it of items || []) {
    const b = it && it.json;
    if (!b || typeof b !== 'object') continue;
    n++;
    let e = null;
    if (typeof b.data === 'string' && /timeout|timed out|502|503|504/i.test(b.data)) {
      e = { node, code: 'TIMEOUT', message: b.data.slice(0, 300) };
    } else if (b.error && !b.code) {
      e = { node, code: null, message: String(b.error).slice(0, 300) };
    } else if (b.code || b.message) {
      e = { node, code: b.code ?? null, message: b.message ?? '',
            details: b.details ?? null, hint: b.hint ?? null };
    }
    if (!e) continue;
    const key = String(e.code ?? e.message).slice(0, 60);
    kinds[key] = (kinds[key] || 0) + 1;
    if (!first || kinds[key] > kinds[String(first.code ?? first.message).slice(0, 60)]) first = e;
  }
  if (!first) return null;
  const key = String(first.code ?? first.message).slice(0, 60);
  first.count = kinds[key];
  first.of = n;
  first.kinds = kinds;
  return first;
}

for (const node of AD4_WRITE_NODES) {
  const e = ad4WriteError(node);
  if (!e) continue;
  // 42501 is the one worth naming, because the cause is never in the code.
  if (String(e.code) === 'TIMEOUT') {
    throw new Error(
      `Supabase did not answer ${e.count} of ${e.of} write(s) at "${e.node}": ${e.message}. ` +
      `That is the DATABASE being too busy to reply, not a bad row - retrying the same run ` +
      `harder will not help. Check whether several workflows are running at once, and look ` +
      `at the Supabase project's load. Whatever did not time out was written; the rest was not.`);
  }
  if (String(e.code) === '42501' || /permission denied/i.test(e.message)) {
    throw new Error(
      `Supabase REFUSED the write at "${e.node}": ${e.message} (${e.code}). The key was ` +
      `already checked at "Run now?" and claims to be the service key, so this is the ` +
      `DATABASE side: service_role has no INSERT on that table. Run sql/ad4_38_grants.sql ` +
      `in the Supabase SQL editor - it grants the write path back, then prints one row per ` +
      `ingest table saying whether the service key can write it. Nothing was written.`);
  }
  if (String(e.code) === '42P01') {
    throw new Error(
      `Supabase has no such table for "${e.node}": ${e.message}. The sql/ files that create ` +
      `it have not been run - sql/ad4_98_ui_health.sql names which file owns which table. ` +
      `Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write at "${e.node}": ${e.message}` +
    (e.code ? ` (${e.code})` : '') + (e.details ? ` - ${e.details}` : '') +
    (e.hint ? ` Hint: ${e.hint}` : '') + ' Nothing was written.');
}

const p = $('Build snapshots').first().json;
const states = Object.entries(p.byState || {}).map(([k, v]) => `${k}=${v}`).join(' ');
const rows = p.n || 0;
const summary =
  `AD4 P0.3: ${rows} book snapshots written from ${p.requested} bands` +
  (p.failed ? `, ${p.failed} failed` : '') + `. ${states}`;
const status = p.failed > rows ? 'attention' : 'ok';
const detail = { requested: p.requested, failed: p.failed, by_state: p.byState };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P0.3_book_volume_snapshot', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];

// AD4-KEY-CHECK
// THE KEY IS NOT IN THIS FILE ANY MORE, AND THAT IS THE POINT.
//
// Every Supabase node in this workflow authenticates with an n8n SUPABASE
// CREDENTIAL rather than a key pasted into the Config node. That is one place
// to set it instead of twelve, it is encrypted at rest in n8n, and exporting
// this workflow can no longer leak it - the old shape had the service key
// sitting in plain text inside a JSON file that gets emailed around.
//
// SET IT UP ONCE, BEFORE IMPORTING ANYTHING:
//   n8n -> Credentials -> New -> Supabase API
//     Name         AD4 Supabase        <- this name exactly
//     Host         https://<your-project-ref>.supabase.co
//     Service Role the SERVICE ROLE key (Project Settings -> API keys)
//
// The name matters because every Supabase node in every AD4 workflow is
// already bound to a credential called AD4 Supabase. Create it first and
// n8n links all of them on import - nothing to pick node by node. Import
// first and the nodes come in unbound, and you pick the credential on each
// one by hand; it works, it is just ~57 dropdowns instead of zero.
//
// The credential sends `apikey` and `Authorization: Bearer` itself, which is
// exactly what these nodes used to set by hand.
//
// WHAT STILL CHECKS THE KEY. This node can no longer read it - a credential
// is not visible to an expression, by design. Two things downstream do:
//
//   the schedule gate, immediately below. sql/ad4_38 revokes should_run from
//   anon, so a credential holding the publishable key is refused HERE, two
//   nodes in, before a single row is fetched.
//
//   the write guard in the Summary node, which names any refusal the
//   database gives and refuses to report success on a run that wrote nothing.
//
// supabase_url stays in Config because an expression has to build the request
// URL and cannot read the credential's host. It is not a secret.
{
  const cfg = $('Config').first().json ?? {};
  const url = String(cfg.supabase_url ?? '').trim();
  if (!url) {
    throw new Error(
      'Config -> supabase_url is empty. Set it to exactly ' +
      'https://<your-project-ref>.supabase.co - no trailing slash and no /rest/v1, ' +
      'which every node below appends itself. The KEY does not go here: it belongs in ' +
      'the n8n Supabase credential (Credentials -> New -> Supabase API), which is ' +
      'where the nodes now read it from.');
  }
  if (!/^https:\/\//.test(url) || /\/rest\b/.test(url) || /\/$/.test(url)) {
    throw new Error(
      `Config -> supabase_url is "${url}", which is not the shape every node below ` +
      'expects: https://<your-project-ref>.supabase.co, no trailing slash, no /rest/v1. ' +
      'Nothing was fetched and nothing was written.');
  }
}

// AN ENDPOINT THIS FILE CANNOT KNOW.
//
// P0.2-P0.5 are RECONSTRUCTIONS. The Supabase half is grounded in the real
// schema and is safe; the Polymarket half never was. These files used to ship
// with a plausible-looking URL already filled in, which is worse than shipping
// none: it reads as authoritative, so nobody changes it, and the run dies four
// nodes later with a message about response shapes. That is exactly how this
// wasted an afternoon.
//
// So the field ships EMPTY and the run stops here - before any HTTP call,
// before any database read - saying where the real value is.
{
  const cfg = $('Config').first().json ?? {};
  const missing = Object.keys(cfg)
    .filter((k) => k.endsWith('_url') && k !== 'supabase_url')
    .filter((k) => !String(cfg[k] ?? '').trim());
  if (missing.length) {
    throw new Error(
      `Config.${missing.join(' and Config.')} is empty, and this file cannot fill it in. ` +
      `Open your OWN working P0.2-P0.5 in n8n, click its Polymarket HTTP node, copy the URL ` +
      `from it, and paste it here. Those workflows are what put 841 markets and 122,000 trades ` +
      `in this database - they are the authority on the endpoint, not this reconstruction. ` +
      `Nothing was fetched and nothing was written.`);
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot even call should_run, and a key that cannot do that cannot write
// either - so stop, rather than failing open into a run that writes nothing.
//
// THIS NODE CANNOT CHECK THE KEY ITSELF ANY MORE - it is in the credential,
// which an expression cannot read. So a refusal here is one of two things and
// both stop the run: the credential holds the anon/publishable key rather than
// the service role key, or service_role has not been granted what it needs.
// Either way every write below would be refused the same way, so there is
// nothing to gain by going on. ad4_38's output tells you which it was.
//
// ad4_38 revokes should_run from anon for this reason: it was granted so the
// Workflows page could preview a cadence, that page reads v_execution_budget
// instead, and the grant only let a bad key through the gate.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). Every write below ` +
    `would be refused the same way, so nothing was fetched and nothing was written. Two ` +
    `things cause this and the workflow cannot tell them apart, because the key now lives ` +
    `in the n8n credential where an expression cannot read it. (1) THE KEY: open n8n -> ` +
    `Credentials -> the Supabase account these nodes use and check Service Role Secret ` +
    `holds the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
    `key beginning sb_secret_) - an anon key gets exactly this error, because anon is ` +
    `granted SELECT and nothing else. NEVER put the service key anywhere starting ` +
    `NEXT_PUBLIC_. (2) THE DATABASE: service_role has not been granted what it needs. Run ` +
    `sql/ad4_38_grants.sql in the Supabase SQL editor - it grants the write path back and ` +
    `then prints one row per ingest table saying whether the service key can write it, ` +
    `which also tells you which of the two it was.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;
